from __future__ import annotations
import ast
import os
import sys
import sysconfig
import tomllib
from pathlib import Path

root = Path('.')
py_files = [p for p in root.rglob('*.py') if not any(part in {'.venv','__pycache__','.git','.mypy_cache','.pytest_cache','.uv-cache'} for part in p.parts)]
stdlib = set(sys.stdlib_module_names)
stdlib.update({'__future__'})
local_roots = {'idaho_vault'}
local_files = {p.stem for p in py_files if p.parent == root}
local_roots.update(local_files)
# scripts import sibling modules by bare name
for d in ['scripts']:
    local_roots.update(p.stem for p in (root/d).glob('*.py')) if (root/d).exists() else None

imports = {}
syntax_errors=[]
for p in py_files:
    try:
        tree = ast.parse(p.read_text(encoding='utf-8'), filename=str(p))
    except Exception as e:
        syntax_errors.append((str(p), repr(e)))
        continue
    mods=set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                mods.add(alias.name.split('.')[0])
        elif isinstance(node, ast.ImportFrom):
            if node.level == 0 and node.module:
                mods.add(node.module.split('.')[0])
    imports[str(p)] = sorted(mods)

external = {}
for file, mods in imports.items():
    for m in mods:
        if m in stdlib or m in local_roots:
            continue
        external.setdefault(m, []).append(file)

with open('pyproject.toml','rb') as f:
    pyproject=tomllib.load(f)
project_deps=pyproject.get('project',{}).get('dependencies',[])
# crude normalize package/project names
def dep_name(spec):
    s=spec.split(';',1)[0].strip()
    for sep in ['[','<','>','=','!','~']:
        s=s.split(sep,1)[0]
    return s.strip().lower().replace('_','-')

def mod_to_pkg(m):
    return {
        'flask':'flask',
        'crewai':'crewai',
        'pydantic':'pydantic',
        'huggingface_hub':'huggingface-hub',
        'requests_oauthlib':'requests-oauthlib',
    }.get(m, m.lower().replace('_','-'))

declared={dep_name(d) for d in project_deps}
req_names=set()
req=Path('requirements.txt')
if req.exists():
    for line in req.read_text(encoding='utf-8').splitlines():
        line=line.strip()
        if not line or line.startswith('#') or line.startswith('    #'):
            continue
        name=line.split('==',1)[0].split('[',1)[0].lower().replace('_','-')
        req_names.add(name)

print('PY_FILES', len(py_files))
print('SYNTAX_ERRORS', syntax_errors)
print('PROJECT_DEPS', sorted(declared))
print('EXTERNAL_IMPORTS')
for m, files in sorted(external.items()):
    pkg=mod_to_pkg(m)
    print(f'{m}\tpackage={pkg}\tdeclared={pkg in declared}\trequirements={pkg in req_names}\tfiles={len(files)}')
    for f in files[:8]:
        print(f'  - {f}')
    if len(files)>8:
        print(f'  ... {len(files)-8} more')
