        'requests':'requests',
        'anthropic':'anthropic',
        'mcp_guardrails':'mcp-guardrails',
    }.get(m, m.lower().replace('_','-'))

def dep_name(spec):
    s=spec.split(';',1)[0].strip()
    for sep in ['[','<','>','=','!','~']:
        s=s.split(sep,1)[0]
    return s.strip().lower().replace('_','-')
with open('pyproject.toml','rb') as f:
    pyproject=tomllib.load(f)
declared={dep_name(d) for d in pyproject.get('project',{}).get('dependencies',[])}
req_names=set()
for line in Path('requirements.txt').read_text(encoding='utf-8').splitlines():
    line=line.strip()
    if not line or line.startswith('#') or line.startswith('    #'):
        continue
    req_names.add(line.split('==',1)[0].split('[',1)[0].lower().replace('_','-'))
external={}
for p in py_files:
    tree=ast.parse(p.read_text(encoding='utf-8'), filename=str(p))
    for node in ast.walk(tree):
        m=None
        if isinstance(node, ast.Import):
            for alias in node.names:
                m=alias.name.split('.')[0]
                if m not in stdlib and m not in local_roots:
                    external.setdefault(m,set()).add(str(p))
        elif isinstance(node, ast.ImportFrom) and node.level==0 and node.module:
            m=node.module.split('.')[0]
            if m not in stdlib and m not in local_roots:
