print('OWNED_PY_FILES', len(py_files))
for p in py_files:
    print('FILE', p)
print('EXTERNALS')
for m in sorted(external):
    pkg=mod_to_pkg(m)
    print(f'{m}\tpackage={pkg}\tpyproject={pkg in declared}\trequirements={pkg in req_names}\tfiles={len(external[m])}')
    for f in sorted(external[m]): print('  -',f)
